export function renderDevPatch({ host, client, preset, conversation }) {
  const lines = [
    "# Generated by scripts/dev-patch.mjs; do not edit.",
    "- insert:",
    "    - id: dev-digital-life-host",
    `      name: '${host}'`,
    ...(conversation ? ["      config:", "        features: [identity, conversation]"] : []),
    "    - id: dev-digital-life-client",
    `      name: '${client}'`,
    "",
  ];
  return lines.join("\n") + (conversation ? preset : "");
}
